class Solution(object):
    def matrixScore(self, A):
        """
        :type A: List[List[int]]
        :rtype: int
        """
        m, n = len(A), len(A[0])
        ans = m * (1 << (n - 1))
        for j in range(1, n):
            n_ones = 0
            for i in range(m):
                if A[i][0] == 1:
                    n_ones += A[i][j]
                else:
                    n_ones += (1 - A[i][j])
            n_ones = max(n_ones, m - n_ones)
            ans += n_ones * (1 << (n - j - 1))
        return ans
